INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2009, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2009): Centro de Seleça de Promoção de Event ⚫ Não serão objeto de conhecimento recursos em desacordo com o item 8 do Edital de 19/1/2009- Concurso de Admissão à Carreira de Diplomata. Informações adicionais: telefone 0(XX) 61 3448-0100; . E permitida a reprodução deste material apenas para fins didáticos. Ministério das Relações Exteriores Instituto Rio Branco Admissão à Carreira de Diplomata LEIA COM A | Ao receber este caderno, confira atentamente se o tipo de caderno-Caderno VERMELHO-coincide.com o que está registrado em sua folha de respostas e no rodapé de cada página numerada deste caderno. Em seguida, verifique se ele contém quarenta e uma questões, correspondentes à segunda etapa da prova objetiva, corretamente ordenadas de 40 a 80.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2009, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2009): Centro de Seleça de Promoção de Event ⚫ Não serão objeto de conhecimento recursos em desacordo com o item 8 do Edital de 19/1/2009- Concurso de Admissão à Carreira de Diplomata. Informações adicionais: telefone 0(XX) 61 3448-0100; . E permitida a reprodução deste material apenas para fins didáticos. Ministério das Relações Exteriores Instituto Rio Branco Admissão à Carreira de Diplomata LEIA COM A | Quando autorizado pelo aplicador, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: A cultura forma sábios; a educação, homens.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2009, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2009): Centro de Seleça de Promoção de Event ⚫ Não serão objeto de conhecimento recursos em desacordo com o item 8 do Edital de 19/1/2009- Concurso de Admissão à Carreira de Diplomata. Informações adicionais: telefone 0(XX) 61 3448-0100; . E permitida a reprodução deste material apenas para fins didáticos. Ministério das Relações Exteriores Instituto Rio Branco Admissão à Carreira de Diplomata LEIA COM A | Caso o caderno esteja incompleto, tenha qualquer defeito, ou haja divergência quanto ao tipo de caderno, solicite ao aplicador mais próximo que tome as providências cabíveis, pois não serão aceitas reclamações posteriores neste sentido.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2009, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2009): Centro de Seleça de Promoção de Event ⚫ Não serão objeto de conhecimento recursos em desacordo com o item 8 do Edital de 19/1/2009- Concurso de Admissão à Carreira de Diplomata. Informações adicionais: telefone 0(XX) 61 3448-0100; . E permitida a reprodução deste material apenas para fins didáticos. Ministério das Relações Exteriores Instituto Rio Branco Admissão à Carreira de Diplomata LEIA COM A | Não serão distribuidas folhas suplementares para rascunho.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2009, 'Português', 'Interpretação de texto', 'Item 5 (TPS 2009): Centro de Seleça de Promoção de Event ⚫ Não serão objeto de conhecimento recursos em desacordo com o item 8 do Edital de 19/1/2009- Concurso de Admissão à Carreira de Diplomata. Informações adicionais: telefone 0(XX) 61 3448-0100; . E permitida a reprodução deste material apenas para fins didáticos. Ministério das Relações Exteriores Instituto Rio Branco Admissão à Carreira de Diplomata LEIA COM A | Você encontrará dois tipos de questões objetivas: múltipla escolha e CERTO ou ERRADO. Nas questões do tipo múltipla escolha, marque, em cada uma, a única opção correta (A, B, C, D ou E), de acordo com o respectivo comando. Nas questões do tipo CERTO ou ERRADO, que têm quatro itens cada, marque, para cada item: o campo designado com o código C, caso julgue o item CERTO, ou o campo designado com o código E, caso julgue o item ERRADO. 6 7 8', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2009, 'Política Internacional', NULL, 'Item 6 (TPS 2009) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
